#include <bits/stdc++.h>
using namespace std;

struct Point {
    int v, w, x, y, z;
    Point(int a, int b, int c, int d, int e) : v(a), w(b), x(c), y(d), z(e) {}
    double magnitude() const {
        return sqrt(v * v + w * w + x * x + y * y + z * z);
    }
};

bool angle(const Point& a, const Point& b) {
    double magA = a.magnitude();
    double magB = b.magnitude();
    double dotProduct = a.v * b.v + a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z;
    double cosTheta = dotProduct / (magA * magB);
    // To handle floating point inaccuracies
    if (cosTheta > 1.0) cosTheta = 1.0;
    if (cosTheta < -1.0) cosTheta = -1.0;
    double angleDeg = acos(cosTheta) * 180.0 / M_PI;
    return angleDeg < 90;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n > 11) {
        cout << 0 << "\n";
        return 0;
    }
    vector<Point> pts;
    for (int i = 0; i < n; i++) {
        int a, b, c, d, e;
        cin >> a >> b >> c >> d >> e;
        pts.emplace_back(a, b, c, d, e);
    }
    unordered_set<int> resultSet;
    for (int i = 0; i < n; i++) {
        bool valid = true;
        for (int j = 0; j < n && valid; j++) {
            if (i == j) continue;
            for (int k = 0; k < n && valid; k++) {
                if (i == k || j == k) continue;
                Point p1 = pts[j];
                Point p2 = pts[k];
                Point p3 = pts[i];
                Point v1(p1.v - p3.v, p1.w - p3.w, p1.x - p3.x, p1.y - p3.y, p1.z - p3.z);
                Point v2(p2.v - p3.v, p2.w - p3.w, p2.x - p3.x, p2.y - p3.y, p2.z - p3.z);
                if (angle(v1, v2)) {
                    valid = false;
                }
            }
        }
        if (valid) {
            resultSet.insert(i + 1);
        }
    }
    if (resultSet.empty()) {
        cout << 0 << "\n";
    } else {
        cout << resultSet.size() << "\n";
        for (int index : resultSet) {
            cout << index << "\n";
        }
    }
    return 0;
}

